    /// Whether the text is final. Only an interim transcription isn't.
    public let final: Bool
    /// Identifier for the user who spoke or typed. For chat, set only when the transport knows the sender, such as
    /// Daily and LiveKit.
    public let userId: String?
    /// For chat, the id of the client's `send-text` message.
    public let msgId: String?
    /// For a transcription, how the user said it, when the STT service reports a reading with it. Part of expressive
    /// conversation (alpha).
    public let perception: [UserPerceptionSignal]?
    /// For a transcription, who said it, when the STT service's diarization tells speakers apart.
    public let speaker: TranscriptionSpeaker?

    enum CodingKeys: String, CodingKey {
        case text
        case inputType = "input_type"
        case timestamp
        case final
        case userId = "user_id"
        case msgId = "msg_id"
        case perception
        case speaker
    }

    public init(
        text: String,
        inputType: InputType,
        timestamp: String,
        final: Bool,
        userId: String? = nil,
        msgId: String? = nil,
        perception: [UserPerceptionSignal]? = nil,
        speaker: TranscriptionSpeaker? = nil
    ) {
        self.text = text
        self.inputType = inputType
        self.timestamp = timestamp
        self.final = final
        self.userId = userId
        self.msgId = msgId
        self.perception = perception
        self.speaker = speaker
    }
}

/// A label of a perception signal, with how sure the reading is.
public struct UserPerceptionLabel: Codable, Equatable {
    /// The label, such as `"frustrated"`.
    public let label: String
    /// How sure the reading is, from 0 to 1.
    public let confidence: Double

    public init(label: String, confidence: Double) {
        self.label = label
        self.confidence = confidence
    }
}

/// One signal of a reading of how the user spoke.
public struct UserPerceptionSignal: Codable, Equatable {
    /// What is read, such as `"tone"`.
    public let name: String
    /// The likeliest labels, likeliest first, for a signal read as labels.
    public let labels: [UserPerceptionLabel]
    /// The measure, for a signal read as a value.
    public let value: Double?

    public init(name: String, labels: [UserPerceptionLabel], value: Double? = nil) {
        self.name = name
        self.labels = labels
        self.value = value
    }
}
